const mode = (msg.payload || '').trim();
const tod = msg.timeOfDay;
const popcorn = msg.input_boolean?.popcorn;

msg.action = null;

// VACATION GATE (2026-07-22): skip the morning/evening routine entirely while
// on vacation. It was briefly setting Mode to Home twice a day (1s alarm
// disarm, shades cycling, music + outdoor lights left on with nobody home).
if (mode === 'Vacation') {
    msg.action = { type: 'none' };
    return msg;
}

// AWAY AT 06:30 -> VACATION (2026-11-24): if the mode is still Away when the 06:30
// Beginning-of-Day run starts and nobody in the family is home, the house goes
// into Vacation instead of being flipped to Home (which also disarmed the alarm
// and opened the shades in an empty house). Only runs 06:30-08:00 so the earlier
// wake-condition path (04:00-06:30) is unchanged. If anyone is home, the original
// behaviour below still applies.
if (mode === 'Away' && tod === 'morning') {
    const nowD = new Date();
    const mins = nowD.getHours() * 60 + nowD.getMinutes();
    const st = global.get('homeassistant.homeAssistant.states') || {};
    const FAMILY = ['person.justin_bennett','person.helen','person.matthew','person.olivia','person.jonathan'];
    const known = FAMILY.filter(id => st[id] && st[id].state);
    const familyHome = known.some(id => st[id].state === 'home');
    // Only act when person states are actually loaded (e.g. not right after a restart).
    if (mins >= 6*60 + 30 && mins < 8*60 && known.length > 0 && !familyHome) {
        node.status({fill:'blue', shape:'dot', text:'Away @06:30 -> Vacation ' + nowD.toLocaleTimeString()});
        msg.action = { type: 'vacation' };
        return msg;
    }
}

// Time guard: treat Home mode same as Night during morning window (4-8 AM)
// This prevents an HA restart from bypassing the morning routine
const hour = new Date().getHours();
const isMorningWindow = (hour >= 4 && hour < 8);

if (['Night', 'Away', 'Vacation'].includes(mode) || (mode === 'Home' && isMorningWindow)) {
    msg.action = { type: 'checkSchoolDay' };
} else if (tod === 'evening' && popcorn !== 'on') {
    msg.action = { type: 'checkPopcorn' };
} else {
    msg.action = { type: 'none' };
}

return msg;
